using Microsoft.VisualStudio.TestTools.UnitTesting;
using Commerce;

namespace Commerce.Tests;

[TestClass]
public class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    // --- AddItem ---

    [TestMethod]
    public void AddItem_SingleItem_IncreasesTotal()
    {
        _cart.AddItem("SKU1", 10.00m, 2);
        Assert.AreEqual(20.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleItems_SumsCorrectly()
    {
        _cart.AddItem("SKU1", 5.00m, 3);
        _cart.AddItem("SKU2", 12.50m, 1);
        Assert.AreEqual(27.50m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_DuplicateSku_BothCounted()
    {
        _cart.AddItem("SKU1", 10.00m, 1);
        _cart.AddItem("SKU1", 10.00m, 1);
        Assert.AreEqual(20.00m, _cart.GetTotal());
    }

    // --- RemoveItem ---

    [TestMethod]
    public void RemoveItem_ExistingItem_ReturnsTrue()
    {
        _cart.AddItem("SKU1", 10.00m, 1);
        Assert.IsTrue(_cart.RemoveItem("SKU1"));
    }

    [TestMethod]
    public void RemoveItem_ExistingItem_ReducesTotal()
    {
        _cart.AddItem("SKU1", 10.00m, 2);
        _cart.AddItem("SKU2", 5.00m, 1);
        _cart.RemoveItem("SKU1");
        Assert.AreEqual(5.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistentItem_ReturnsFalse()
    {
        Assert.IsFalse(_cart.RemoveItem("NOPE"));
    }

    [TestMethod]
    public void RemoveItem_DuplicateSkus_RemovesAll()
    {
        _cart.AddItem("SKU1", 10.00m, 1);
        _cart.AddItem("SKU1", 10.00m, 1);
        _cart.RemoveItem("SKU1");
        Assert.AreEqual(0.00m, _cart.GetTotal());
    }

    // --- GetTotal ---

    [TestMethod]
    public void GetTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_AfterAllItemsRemoved_ReturnsZero()
    {
        _cart.AddItem("SKU1", 25.00m, 4);
        _cart.RemoveItem("SKU1");
        Assert.AreEqual(0.00m, _cart.GetTotal());
    }
}

